// Generated by scripts/support/generate-passkey-guide.mjs. Edit the source catalog/runtime.
const PASSKEY_SUPPORT_COPY = {"en":{"name":"English","title":"Passkeys: change devices and restore your wallet","intro":"Open wallet.getyoursats.com in a full browser and choose Restore for your existing wallet. Use the original passkey and the same wallet label if asked. Start or a newly created passkey can create a different wallet.","safety":"Keep the old device, passkey and wallet data until recovery is verified. Finding a passkey or completing sign-in does not prove that the same wallet has been restored. Menu names vary by system version.","language":"Guide language","source":"Official platform instructions","contact":"Still stuck? Contact support with device, OS and browser versions, wallet URL, error text and whether a passkey appeared. Never send recovery words, keys, PINs or passkey secrets.","scenarios":{"google-to-iphone":{"title":"Google passkey: Android → iPhone","steps":["Install and open Chrome on the iPhone. Sign in to the Google account that holds the original passkey. The Google search app alone is not Chrome or its passkey provider.","On iOS 17 or later, search Settings for AutoFill & Passwords. Enable Chrome as a password/passkey provider.","Open the wallet in Chrome and choose Restore. If prompted, unlock Google Password Manager with its PIN or the requested previous device screen lock. Select the existing passkey."]},"google-to-android":{"title":"Google passkey: iPhone or Android → Android","steps":["Use this route only if the original passkey is stored in Google Password Manager, including one created on an iPhone using Chrome.","On the new Android device, sign in to the same Google account and enable Google Password Manager for passwords/passkeys in Settings. Allow sync and unlock the manager when prompted.","Open the same wallet website in Chrome, choose Restore and select the original passkey. An Apple Passwords passkey does not appear just because you sign in to Google."]},"apple-to-apple":{"title":"Apple Passwords: iPhone → iPhone or iPad","steps":["Sign in to the same Apple Account on the new device. In iCloud settings, enable Passwords & Keychain sync and complete any account-recovery prompts.","Enable Apple Passwords for AutoFill and check that the wallet passkey is present in Passwords.","Open the original wallet website in Safari, choose Restore and select that passkey."]},"apple-to-android-qr":{"title":"Apple Passwords → Android, with the iPhone nearby","steps":["On Android, open the wallet and choose Restore. If offered, select the option to use a passkey from another phone or tablet.","Keep both devices nearby with Bluetooth and internet enabled. Scan the displayed QR code with the iPhone holding the original passkey and approve on that iPhone.","This uses the iPhone-held credential; it does not copy it to Android. Wallet support for this route remains unverified. If unavailable or unsupported, stop and preserve the working wallet."]},"move-provider":{"title":"Moving between Apple Passwords and Google Password Manager","steps":["This is a platform migration option, not a verified GetYourSats recovery route. Passkey transfer may not preserve the secret needed to unlock the same wallet. Keep the original credential and device.","Where both apps offer secure passkey transfer, use the source manager’s transfer/export option and select the destination manager. For an import into Google on iPhone, choose Chrome and authenticate to complete the import. A password CSV is not a passkey backup.","Sync the destination manager to the new device, then verify the wallet using the checklist below. If transfer is unavailable, use a compatible existing device or an independently verified backup for this exact wallet."]},"missing-passkey":{"title":"No passkey appears, or sign-in is cancelled","steps":["Open the exact original wallet website in a full browser, outside the Google search app or an in-app browser. Check the password manager, account, sync and AutoFill provider. Update the browser and OS.","Retry Restore and complete the system prompt. A cancellation message can also mean no matching credential, timeout or an unavailable provider; it does not prove you cancelled.","If the passkey appears but the wallet cannot open, the provider may lack the wallet’s required cryptographic support. Keep the original wallet; do not create a replacement passkey or clear data to fix it. Contact support."]},"lost-device":{"title":"The old phone is lost, broken or already erased","steps":["First recover access to the original password-manager account and its synced passkeys on a compatible device. Apple Passwords does not automatically sync to Android. QR sign-in requires an available device holding the passkey.","If that is unavailable, use only an independent recovery backup already verified for this exact wallet. A recovery phrase from a different wallet will not recover these funds.","Without a compatible original passkey or a verified backup, support, email verification and a Lightning username cannot recreate the wallet keys. Do not delete any remaining wallet data."]},"verify-wallet":{"title":"Before you erase or replace the old device","steps":["Compare the restored wallet identity, balance and payment history with the original. A wallet label alone is not proof. Stop if they differ or an unexpected empty wallet appears.","Close and reopen the wallet on the new device to check access persists. Keep the old device and independent backup until recovery is verified.","If any check fails, keep the original wallet intact and contact support. Do not send more funds or create a new wallet to fix recovery."]}},"nav":"Restore wallet access"},"hi":{"name":"हिन्दी","title":"पासकी: डिवाइस बदलें और अपना वॉलेट पुनर्स्थापित करें","intro":"पूरे ब्राउज़र में wallet.getyoursats.com खोलें और मौजूदा वॉलेट के लिए Restore चुनें। मूल पासकी और पूछे जाने पर वही वॉलेट लेबल इस्तेमाल करें। Start या नई पासकी से अलग वॉलेट बन सकता है।","safety":"रिकवरी की पुष्टि होने तक पुराना डिवाइस, पासकी और वॉलेट डेटा सुरक्षित रखें। पासकी मिलना या साइन-इन पूरा होना उसी वॉलेट की रिकवरी का प्रमाण नहीं है। सिस्टम संस्करण के अनुसार मेनू के नाम बदल सकते हैं।","language":"गाइड की भाषा","source":"प्लेटफ़ॉर्म के आधिकारिक निर्देश","contact":"फिर भी समस्या है? सहायता को डिवाइस, OS और ब्राउज़र संस्करण, वॉलेट URL, त्रुटि और पासकी दिखी या नहीं, बताएँ। रिकवरी शब्द, कुंजियाँ, PIN या पासकी के रहस्य कभी न भेजें।","scenarios":{"google-to-iphone":{"title":"Google पासकी: Android → iPhone","steps":["iPhone पर Chrome इंस्टॉल करके खोलें। मूल पासकी वाले Google खाते में साइन-इन करें। केवल Google खोज ऐप, Chrome या उसका पासकी प्रदाता नहीं है।","iOS 17 या बाद के संस्करण में Settings में AutoFill & Passwords खोजें। पासवर्ड/पासकी प्रदाता के रूप में Chrome चालू करें।","Chrome में वॉलेट खोलकर Restore चुनें। माँगे जाने पर Google Password Manager का PIN या माँगा गया पुराने डिवाइस का स्क्रीन लॉक डालें। मौजूदा पासकी चुनें।"]},"google-to-android":{"title":"Google पासकी: iPhone या Android → Android","steps":["यह तरीका तभी अपनाएँ जब मूल पासकी Google Password Manager में हो, जिसमें iPhone पर Chrome से बनाई गई पासकी भी शामिल है।","नए Android पर उसी Google खाते में साइन-इन करें। Settings में पासवर्ड/पासकी के लिए Google Password Manager चालू करें। सिंक होने दें और माँगे जाने पर मैनेजर अनलॉक करें।","Chrome में वही वॉलेट वेबसाइट खोलें, Restore और मूल पासकी चुनें। Google में साइन-इन करने मात्र से Apple Passwords की पासकी नहीं आती।"]},"apple-to-apple":{"title":"Apple Passwords: iPhone → iPhone या iPad","steps":["नए डिवाइस पर उसी Apple Account में साइन-इन करें। iCloud में Passwords & Keychain सिंक चालू करें और खाते की रिकवरी के निर्देश पूरे करें।","AutoFill के लिए Apple Passwords चालू करें और Passwords में वॉलेट की पासकी मौजूद होने की जाँच करें।","Safari में मूल वॉलेट वेबसाइट खोलें, Restore और वही पासकी चुनें।"]},"apple-to-android-qr":{"title":"Apple Passwords → Android, जब iPhone पास हो","steps":["Android पर वॉलेट खोलकर Restore चुनें। उपलब्ध हो तो दूसरे फ़ोन या टैबलेट की पासकी इस्तेमाल करने का विकल्प चुनें।","दोनों डिवाइस पास रखें, Bluetooth और इंटरनेट चालू रखें। मूल पासकी वाले iPhone से दिखाया गया QR कोड स्कैन करें और उसी iPhone पर अनुमति दें।","इससे iPhone की पासकी इस्तेमाल होती है, Android पर कॉपी नहीं होती। इस तरीके से वॉलेट रिकवरी अभी सत्यापित नहीं है। विकल्प उपलब्ध या समर्थित न हो तो रुकें और चालू वॉलेट सुरक्षित रखें।"]},"move-provider":{"title":"Apple Passwords और Google Password Manager के बीच बदलना","steps":["यह प्लेटफ़ॉर्म का माइग्रेशन विकल्प है, सत्यापित GetYourSats रिकवरी तरीका नहीं। पासकी ट्रांसफ़र में उसी वॉलेट को खोलने वाला रहस्य सुरक्षित न रह पाए। मूल पासकी और डिवाइस रखें।","दोनों ऐप सुरक्षित पासकी ट्रांसफ़र देते हों तो मूल मैनेजर का ट्रांसफ़र/एक्सपोर्ट विकल्प चुनकर गंतव्य मैनेजर चुनें। iPhone पर Google में आयात के लिए Chrome चुनें और प्रमाणीकरण पूरा करें। पासवर्ड CSV पासकी बैकअप नहीं है।","नए डिवाइस पर गंतव्य मैनेजर सिंक करके नीचे की जाँच करें। ट्रांसफ़र उपलब्ध न हो तो संगत मौजूदा डिवाइस या इसी वॉलेट का स्वतंत्र रूप से सत्यापित बैकअप इस्तेमाल करें।"]},"missing-passkey":{"title":"पासकी नहीं दिखती या साइन-इन रद्द हो जाता है","steps":["मूल वॉलेट वेबसाइट पूरे ब्राउज़र में खोलें, Google खोज ऐप या किसी ऐप के अंदर के ब्राउज़र में नहीं। पासवर्ड मैनेजर, खाता, सिंक और AutoFill प्रदाता जाँचें। ब्राउज़र और OS अपडेट करें।","Restore फिर चुनें और सिस्टम का निर्देश पूरा करें। रद्द होने का संदेश मेल खाती पासकी न मिलने, समय समाप्त होने या प्रदाता उपलब्ध न होने से भी आ सकता है; यह आपके रद्द करने का प्रमाण नहीं है।","पासकी दिखने पर भी वॉलेट न खुले तो प्रदाता में वॉलेट के लिए आवश्यक क्रिप्टोग्राफ़िक सुविधा न हो सकती है। मूल वॉलेट रखें; इसे ठीक करने के लिए नई पासकी न बनाएँ या डेटा न मिटाएँ। सहायता से संपर्क करें।"]},"lost-device":{"title":"पुराना फ़ोन खो गया, टूट गया या मिटा दिया गया है","steps":["पहले संगत डिवाइस पर मूल पासवर्ड-मैनेजर खाते और उसकी सिंक हुई पासकी तक पहुँच वापस पाएँ। Apple Passwords अपने-आप Android से सिंक नहीं होता। QR साइन-इन के लिए पासकी वाला उपलब्ध डिवाइस चाहिए।","यह संभव न हो तो केवल इसी वॉलेट का पहले से सत्यापित स्वतंत्र रिकवरी बैकअप इस्तेमाल करें। दूसरे वॉलेट के रिकवरी शब्द यह धन वापस नहीं ला सकते।","संगत मूल पासकी या सत्यापित बैकअप के बिना सहायता, ईमेल सत्यापन या Lightning नाम वॉलेट की कुंजियाँ दोबारा नहीं बना सकते। बचा हुआ वॉलेट डेटा न मिटाएँ।"]},"verify-wallet":{"title":"पुराना डिवाइस मिटाने या बदलने से पहले","steps":["पुनर्स्थापित वॉलेट की पहचान, बैलेंस और भुगतान इतिहास मूल से मिलाएँ। केवल वॉलेट लेबल प्रमाण नहीं है। अंतर हो या अनपेक्षित खाली वॉलेट खुले तो रुकें।","नए डिवाइस पर वॉलेट बंद करके फिर खोलें और पहुँच जाँचें। रिकवरी की पुष्टि तक पुराना डिवाइस और स्वतंत्र बैकअप रखें।","कोई जाँच सफल न हो तो मूल वॉलेट सुरक्षित रखें और सहायता से संपर्क करें। रिकवरी ठीक करने के लिए और धन न भेजें या नया वॉलेट न बनाएँ।"]}},"nav":"वॉलेट तक पहुँच बहाल करें"},"es":{"name":"Español","title":"Passkeys: cambia de dispositivo y recupera tu cartera","intro":"Abre wallet.getyoursats.com en un navegador completo y elige Restore para tu cartera existente. Usa la passkey original y la misma etiqueta de cartera si se solicita. Start o una passkey nueva pueden crear otra cartera.","safety":"Conserva el dispositivo anterior, la passkey y los datos hasta verificar la recuperación. Encontrar una passkey o iniciar sesión no demuestra que hayas recuperado la misma cartera. Los nombres de los menús varían según la versión.","language":"Idioma de la guía","source":"Instrucciones oficiales de las plataformas","contact":"¿Sigues sin poder acceder? Indica a soporte el dispositivo, las versiones del sistema y navegador, la URL, el error y si apareció una passkey. Nunca envíes palabras de recuperación, claves, PIN ni secretos de passkeys.","scenarios":{"google-to-iphone":{"title":"Passkey de Google: Android → iPhone","steps":["Instala y abre Chrome en el iPhone. Inicia sesión con la cuenta de Google que guarda la passkey original. La aplicación de búsqueda de Google no es Chrome ni su proveedor de passkeys.","En iOS 17 o posterior, busca Autorrelleno y contraseñas en Ajustes. Activa Chrome como proveedor de contraseñas y passkeys.","Abre la cartera en Chrome y elige Restore. Si se solicita, desbloquea el Gestor de contraseñas de Google con su PIN o el bloqueo de pantalla anterior indicado. Selecciona la passkey existente."]},"google-to-android":{"title":"Passkey de Google: iPhone o Android → Android","steps":["Usa esta vía solo si la passkey original está en el Gestor de contraseñas de Google, incluida una creada con Chrome en iPhone.","En el nuevo Android, inicia sesión con la misma cuenta de Google y activa su gestor para contraseñas y passkeys en Ajustes. Espera la sincronización y desbloquéalo si se solicita.","Abre la misma web de la cartera en Chrome, elige Restore y la passkey original. Iniciar sesión en Google no hace aparecer una passkey de Contraseñas de Apple."]},"apple-to-apple":{"title":"Contraseñas de Apple: iPhone → iPhone o iPad","steps":["Inicia sesión con la misma cuenta de Apple en el nuevo dispositivo. Activa la sincronización de Contraseñas y Llavero en iCloud y completa los pasos de recuperación de la cuenta.","Activa Contraseñas de Apple para el autorrelleno y comprueba que contiene la passkey de la cartera.","Abre la web original en Safari, elige Restore y selecciona esa passkey."]},"apple-to-android-qr":{"title":"Contraseñas de Apple → Android, con el iPhone cerca","steps":["Abre la cartera en Android y elige Restore. Si aparece, selecciona la opción de usar una passkey de otro teléfono o tableta.","Mantén ambos dispositivos cerca, con Bluetooth e internet. Escanea el QR con el iPhone que guarda la passkey original y aprueba allí.","Esto usa la credencial del iPhone; no la copia a Android. La recuperación de la cartera por esta vía sigue sin verificarse. Si no está disponible o no se admite, detente y conserva la cartera que funciona."]},"move-provider":{"title":"Cambiar entre Contraseñas de Apple y el gestor de Google","steps":["Es una opción de migración de la plataforma, no una recuperación verificada de GetYourSats. Transferir la passkey podría no conservar el secreto necesario para abrir la misma cartera. Guarda la credencial y el dispositivo originales.","Si ambas aplicaciones ofrecen transferencia segura de passkeys, usa transferir/exportar en el gestor de origen y elige el destino. Para importar a Google en iPhone, selecciona Chrome y autentícate. Un CSV de contraseñas no es una copia de una passkey.","Sincroniza el gestor de destino en el nuevo dispositivo y verifica la cartera con la lista de abajo. Si no puedes transferir, usa un dispositivo compatible que ya tengas o una copia independiente verificada para esta cartera exacta."]},"missing-passkey":{"title":"No aparece ninguna passkey o se cancela el inicio de sesión","steps":["Abre la web original exacta en un navegador completo, fuera de la aplicación de Google o de un navegador integrado. Revisa gestor, cuenta, sincronización y proveedor de autorrelleno. Actualiza navegador y sistema.","Vuelve a elegir Restore y completa el aviso del sistema. El mensaje de cancelación también puede indicar que falta una credencial compatible, que se agotó el tiempo o que el proveedor no está disponible; no demuestra que tú cancelaras.","Si aparece la passkey pero la cartera no abre, el proveedor podría no ofrecer la función criptográfica necesaria. Conserva la cartera original; no crees otra passkey ni borres datos para solucionarlo. Contacta con soporte."]},"lost-device":{"title":"El teléfono anterior se perdió, se rompió o ya se borró","steps":["Primero recupera la cuenta del gestor original y sus passkeys sincronizadas en un dispositivo compatible. Contraseñas de Apple no se sincroniza automáticamente con Android. El QR requiere un dispositivo disponible con la passkey.","Si no es posible, usa únicamente una copia de recuperación independiente ya verificada para esta cartera exacta. La frase de otra cartera no recupera estos fondos.","Sin una passkey original compatible o una copia verificada, soporte, el email verificado y el nombre Lightning no pueden recrear las claves. No borres los datos que queden."]},"verify-wallet":{"title":"Antes de borrar o sustituir el dispositivo anterior","steps":["Compara la identidad, el saldo y el historial de pagos de la cartera recuperada con la original. La etiqueta no basta. Detente si difieren o aparece una cartera vacía inesperada.","Cierra y vuelve a abrir la cartera en el nuevo dispositivo para comprobar que conservas el acceso. Guarda el dispositivo anterior y la copia independiente hasta verificar la recuperación.","Si alguna comprobación falla, conserva intacta la cartera original y contacta con soporte. No envíes más fondos ni crees una cartera nueva para solucionar la recuperación."]}},"nav":"Recuperar el acceso a la cartera"},"pt":{"name":"Português","title":"Passkeys: mudar de dispositivo e recuperar a carteira","intro":"Abra wallet.getyoursats.com num navegador completo e escolha Restore para a carteira existente. Use a passkey original e a mesma etiqueta da carteira, se pedida. Start ou uma nova passkey podem criar outra carteira.","safety":"Guarde o dispositivo antigo, a passkey e os dados até verificar a recuperação. Encontrar uma passkey ou iniciar sessão não prova que recuperou a mesma carteira. Os nomes dos menus variam com a versão.","language":"Idioma do guia","source":"Instruções oficiais das plataformas","contact":"Ainda precisa de ajuda? Indique ao apoio o dispositivo, as versões do sistema e navegador, o URL, o erro e se apareceu uma passkey. Nunca envie palavras de recuperação, chaves, PIN ou segredos de passkeys.","scenarios":{"google-to-iphone":{"title":"Passkey Google: Android → iPhone","steps":["Instale e abra o Chrome no iPhone. Inicie sessão na conta Google que guarda a passkey original. A aplicação de pesquisa Google não é o Chrome nem o seu fornecedor de passkeys.","No iOS 17 ou posterior, procure Preenchimento automático e palavras-passe nas Definições. Ative o Chrome como fornecedor de palavras-passe e passkeys.","Abra a carteira no Chrome e escolha Restore. Se pedido, desbloqueie o Gestor de Palavras-passe Google com o PIN ou o bloqueio de ecrã anterior indicado. Selecione a passkey existente."]},"google-to-android":{"title":"Passkey Google: iPhone ou Android → Android","steps":["Use esta opção apenas se a passkey original estiver no Gestor de Palavras-passe Google, incluindo uma criada no iPhone com Chrome.","No novo Android, entre na mesma conta Google e ative o seu gestor para palavras-passe e passkeys nas Definições. Aguarde a sincronização e desbloqueie o gestor quando pedido.","Abra o mesmo site da carteira no Chrome, escolha Restore e a passkey original. Entrar no Google não faz aparecer uma passkey da aplicação Palavras-passe da Apple."]},"apple-to-apple":{"title":"Palavras-passe Apple: iPhone → iPhone ou iPad","steps":["Entre na mesma conta Apple no novo dispositivo. Ative a sincronização de Palavras-passe e Porta-chaves no iCloud e conclua os pedidos de recuperação da conta.","Ative as Palavras-passe Apple para preenchimento automático e confirme que a passkey da carteira está presente.","Abra o site original no Safari, escolha Restore e selecione essa passkey."]},"apple-to-android-qr":{"title":"Palavras-passe Apple → Android, com o iPhone por perto","steps":["Abra a carteira no Android e escolha Restore. Se disponível, escolha usar uma passkey de outro telefone ou tablet.","Mantenha ambos os dispositivos próximos, com Bluetooth e internet. Leia o QR com o iPhone que tem a passkey original e aprove nesse iPhone.","Isto usa a credencial do iPhone; não a copia para Android. A recuperação da carteira por esta via continua por verificar. Se não estiver disponível ou não for suportada, pare e preserve a carteira que funciona."]},"move-provider":{"title":"Mudar entre Palavras-passe Apple e o gestor Google","steps":["É uma opção de migração da plataforma, não uma recuperação GetYourSats verificada. Transferir a passkey pode não preservar o segredo necessário para abrir a mesma carteira. Guarde a credencial e o dispositivo originais.","Se ambas as aplicações oferecerem transferência segura de passkeys, use transferir/exportar no gestor de origem e escolha o destino. Para importar para Google no iPhone, selecione Chrome e autentique-se. Um CSV de palavras-passe não é uma cópia de uma passkey.","Sincronize o gestor de destino no novo dispositivo e verifique a carteira com a lista abaixo. Se não puder transferir, use um dispositivo compatível existente ou uma cópia independente verificada para esta carteira exata."]},"missing-passkey":{"title":"Não aparece uma passkey ou o início de sessão é cancelado","steps":["Abra o site original exato num navegador completo, fora da aplicação Google ou de um navegador integrado noutra aplicação. Verifique gestor, conta, sincronização e fornecedor de preenchimento automático. Atualize navegador e sistema.","Escolha Restore novamente e conclua o pedido do sistema. Uma mensagem de cancelamento também pode significar que falta uma credencial, que o tempo terminou ou que o fornecedor está indisponível; não prova que cancelou.","Se a passkey aparecer mas a carteira não abrir, o fornecedor pode não ter o suporte criptográfico necessário. Preserve a carteira original; não crie outra passkey nem apague dados para resolver. Contacte o apoio."]},"lost-device":{"title":"O telefone antigo foi perdido, avariou ou já foi apagado","steps":["Primeiro recupere a conta do gestor original e as suas passkeys sincronizadas num dispositivo compatível. As Palavras-passe Apple não sincronizam automaticamente com Android. O QR exige um dispositivo disponível com a passkey.","Se não for possível, use apenas uma cópia de recuperação independente já verificada para esta carteira exata. A frase de outra carteira não recupera estes fundos.","Sem uma passkey original compatível ou cópia verificada, o apoio, o email verificado e o nome Lightning não podem recriar as chaves. Não apague os dados restantes."]},"verify-wallet":{"title":"Antes de apagar ou substituir o dispositivo antigo","steps":["Compare a identidade, o saldo e o histórico de pagamentos da carteira recuperada com a original. A etiqueta não basta. Pare se diferirem ou surgir uma carteira vazia inesperada.","Feche e reabra a carteira no novo dispositivo para confirmar que o acesso se mantém. Guarde o dispositivo antigo e a cópia independente até verificar a recuperação.","Se alguma verificação falhar, mantenha a carteira original intacta e contacte o apoio. Não envie mais fundos nem crie outra carteira para resolver a recuperação."]}},"nav":"Recuperar o acesso à carteira"},"ja":{"name":"日本語","title":"パスキー：端末の変更とウォレットの復元","intro":"通常のブラウザで wallet.getyoursats.com を開き、既存のウォレットには Restore を選んでください。元のパスキーと、求められた場合は同じウォレット名を使います。Start や新しいパスキーでは別のウォレットが作られる場合があります。","safety":"復元を確認するまで、元の端末、パスキー、ウォレットデータを保持してください。パスキーの表示やサインインの成功だけでは、同じウォレットの復元を証明できません。メニュー名はシステムのバージョンで異なります。","language":"ガイドの言語","source":"プラットフォームの公式手順","contact":"解決しない場合は、端末、OS・ブラウザのバージョン、ウォレットのURL、エラー内容、パスキーが表示されたかをサポートに伝えてください。復元フレーズ、鍵、PIN、パスキーの秘密情報は送らないでください。","scenarios":{"google-to-iphone":{"title":"Googleのパスキー：Android → iPhone","steps":["iPhoneにChromeをインストールして開き、元のパスキーを保存したGoogleアカウントにログインします。Google検索アプリだけではChromeやそのパスキープロバイダの代わりになりません。","iOS 17以降では「設定」で「自動入力とパスワード」を検索し、パスワード・パスキーのプロバイダとしてChromeを有効にします。","Chromeでウォレットを開き、Restoreを選びます。求められたらGoogleパスワードマネージャーのPIN、または指定された以前の端末の画面ロックで解除し、既存のパスキーを選択します。"]},"google-to-android":{"title":"Googleのパスキー：iPhoneまたはAndroid → Android","steps":["元のパスキーがGoogleパスワードマネージャーにある場合に使えます。iPhoneのChromeで作ったパスキーも含まれます。","新しいAndroidで同じGoogleアカウントにログインし、設定でGoogleパスワードマネージャーをパスワード・パスキー用に有効にします。同期を待ち、求められたらロックを解除します。","Chromeで元のウォレットのサイトを開き、Restoreと元のパスキーを選びます。GoogleへのログインだけでAppleの「パスワード」のパスキーが表示されることはありません。"]},"apple-to-apple":{"title":"Appleの「パスワード」：iPhone → iPhoneまたはiPad","steps":["新しい端末で同じApple Accountにサインインします。iCloudで「パスワードとキーチェーン」の同期を有効にし、アカウント復旧の案内を完了します。","自動入力でAppleの「パスワード」を有効にし、ウォレットのパスキーが保存されていることを確認します。","Safariで元のウォレットのサイトを開き、Restoreとそのパスキーを選びます。"]},"apple-to-android-qr":{"title":"Appleの「パスワード」→ Android：iPhoneが手元にある場合","steps":["Androidでウォレットを開き、Restoreを選びます。表示された場合は、別のスマートフォンやタブレットのパスキーを使う項目を選びます。","両端末を近くに置き、Bluetoothとインターネットを有効にします。元のパスキーがあるiPhoneで表示されたQRコードを読み取り、そのiPhoneで承認します。","これはiPhoneの認証情報を使用する方法で、Androidへのコピーではありません。この経路によるウォレット復元は未検証です。使えない場合は中止し、利用できるウォレットを保持してください。"]},"move-provider":{"title":"Appleの「パスワード」とGoogleパスワードマネージャー間の移行","steps":["これはプラットフォームの移行機能で、検証済みのGetYourSats復元方法ではありません。パスキーの移行で、同じウォレットを開くための秘密情報が維持されない可能性があります。元の認証情報と端末を保持してください。","両アプリが安全なパスキー転送に対応している場合、元のマネージャーで転送・書き出しを選び、移行先を指定します。iPhoneでGoogleに取り込む場合はChromeを選び、認証して完了します。パスワードのCSVはパスキーのバックアップではありません。","新しい端末で移行先のマネージャーを同期し、下の確認手順でウォレットを検証します。転送できない場合は、対応する既存端末か、このウォレット用に独立して検証したバックアップを使います。"]},"missing-passkey":{"title":"パスキーが表示されない、またはサインインがキャンセルされる","steps":["Google検索アプリやアプリ内ブラウザではなく、通常のブラウザで元と同じウォレットのサイトを開きます。マネージャー、アカウント、同期、自動入力の設定を確認し、ブラウザとOSを更新します。","Restoreを再度選び、システムの案内を完了します。キャンセルの表示は、該当する認証情報がない、時間切れ、プロバイダが利用できない場合にも出るため、利用者が取り消した証拠ではありません。","パスキーが表示されても開けない場合、プロバイダがウォレットに必要な暗号機能に対応していない可能性があります。元のウォレットを保持し、解決のために別のパスキーを作ったりデータを消したりせず、サポートに連絡してください。"]},"lost-device":{"title":"元のスマートフォンを紛失・破損・消去した場合","steps":["まず対応端末で元のパスワードマネージャーのアカウントと同期済みパスキーへのアクセスを復旧します。Appleの「パスワード」はAndroidに自動同期しません。QRサインインにはパスキーを保持する利用可能な端末が必要です。","できない場合、このウォレット用にすでに検証済みの独立した復元バックアップだけを使用します。別のウォレットの復元フレーズでは、この資金を復元できません。","対応する元のパスキーや検証済みバックアップがなければ、サポート、メール認証、Lightningのユーザー名でウォレットの鍵を再作成することはできません。残っているデータを消さないでください。"]},"verify-wallet":{"title":"元の端末を消去・交換する前に","steps":["復元したウォレットの識別情報、残高、支払い履歴を元と比較します。ウォレット名だけでは不十分です。一致しない場合や予期せず空のウォレットが開いた場合は中止してください。","新しい端末でウォレットを閉じて開き直し、引き続きアクセスできることを確認します。復元を検証するまで元の端末と独立したバックアップを保持します。","確認できない項目がある場合は元のウォレットを保持し、サポートに連絡してください。復元の問題を解決するために追加の資金を送ったり、新しいウォレットを作ったりしないでください。"]}},"nav":"ウォレットへのアクセスを復元"},"zh-CN":{"name":"简体中文","title":"通行密钥：更换设备并恢复钱包","intro":"请在完整浏览器中打开 wallet.getyoursats.com，为已有钱包选择 Restore。使用原来的通行密钥，并在提示时输入相同的钱包标签。选择 Start 或创建新通行密钥可能会建立另一个钱包。","safety":"确认恢复成功前，请保留旧设备、通行密钥和钱包数据。找到通行密钥或完成登录，并不代表已恢复同一个钱包。菜单名称可能因系统版本而异。","language":"指南语言","source":"平台官方说明","contact":"仍无法访问？请向客服提供设备、系统和浏览器版本、钱包网址、错误文字，以及是否显示通行密钥。切勿发送恢复词、私钥、PIN 或通行密钥秘密。","scenarios":{"google-to-iphone":{"title":"Google 通行密钥：Android → iPhone","steps":["在 iPhone 上安装并打开 Chrome，登录保存原通行密钥的 Google 账号。仅安装 Google 搜索应用不等于安装 Chrome 或启用其通行密钥提供方。","在 iOS 17 或更高版本的设置中搜索“自动填充与密码”，启用 Chrome 作为密码和通行密钥提供方。","在 Chrome 中打开钱包并选择 Restore。如有提示，使用 Google 密码管理工具的 PIN 或所要求的旧设备屏幕锁解锁，再选择已有通行密钥。"]},"google-to-android":{"title":"Google 通行密钥：iPhone 或 Android → Android","steps":["仅当原通行密钥保存在 Google 密码管理工具中时使用此方法，也包括在 iPhone 上通过 Chrome 创建的通行密钥。","在新 Android 设备上登录同一个 Google 账号，在设置中启用 Google 密码管理工具来提供密码和通行密钥。等待同步，并按提示解锁。","在 Chrome 中打开原钱包网站，选择 Restore 和原通行密钥。登录 Google 并不会让 Apple“密码”中的通行密钥自动出现。"]},"apple-to-apple":{"title":"Apple“密码”：iPhone → iPhone 或 iPad","steps":["在新设备上登录同一个 Apple 账户，在 iCloud 设置中启用“密码与钥匙串”同步，并完成账户恢复提示。","为自动填充启用 Apple“密码”，检查其中是否保存钱包的通行密钥。","在 Safari 中打开原钱包网站，选择 Restore 和该通行密钥。"]},"apple-to-android-qr":{"title":"Apple“密码”→ Android，且 iPhone 在身边","steps":["在 Android 上打开钱包并选择 Restore。如有该选项，选择使用另一部手机或平板上的通行密钥。","将两台设备放在附近，开启蓝牙并连接互联网。用保存原通行密钥的 iPhone 扫描显示的二维码，并在该 iPhone 上批准。","此方式使用 iPhone 上的凭据，不会复制到 Android。钱包通过此路径恢复的能力尚未验证。如果选项不可用或不受支持，请停止并保留仍可使用的钱包。"]},"move-provider":{"title":"在 Apple“密码”和 Google 密码管理工具之间迁移","steps":["这是平台的迁移选项，不是经过验证的 GetYourSats 恢复方式。迁移通行密钥可能无法保留打开同一钱包所需的秘密信息。请保留原凭据和设备。","仅在两款应用都支持安全转移通行密钥时，使用来源管理工具的转移或导出选项，并选择目标管理工具。在 iPhone 上导入 Google 时选择 Chrome，完成身份验证。密码 CSV 不是通行密钥备份。","在新设备上同步目标管理工具，然后按下方清单核验钱包。如无法转移，请使用现有兼容设备，或专门为此钱包独立验证过的备份。"]},"missing-passkey":{"title":"没有显示通行密钥，或登录被取消","steps":["请在完整浏览器中打开准确的原钱包网址，不要使用 Google 搜索应用或应用内浏览器。检查密码管理工具、账号、同步和自动填充提供方，并更新浏览器和系统。","再次选择 Restore 并完成系统提示。取消消息也可能表示没有匹配的凭据、超时或提供方不可用，并不证明是你主动取消。","若显示通行密钥但打不开钱包，提供方可能缺少钱包所需的加密功能。保留原钱包，不要通过新建通行密钥或清除数据来修复，请联系支持。"]},"lost-device":{"title":"旧手机丢失、损坏或已被抹掉","steps":["首先在兼容设备上恢复原密码管理工具账号及其同步的通行密钥。Apple“密码”不会自动同步到 Android。二维码登录需要一台仍可用且持有该通行密钥的设备。","如果无法做到，只使用此前已验证能恢复此钱包的独立备份。其他钱包的恢复词无法恢复这些资金。","没有兼容的原通行密钥或已验证的备份，客服、邮件验证和 Lightning 用户名都无法重建钱包私钥。请勿删除剩余钱包数据。"]},"verify-wallet":{"title":"抹掉或更换旧设备之前","steps":["将恢复的钱包身份、余额和支付历史与原钱包比较。仅钱包标签相同不能证明恢复成功。如果不一致或意外出现空钱包，请停止。","在新设备上关闭并重新打开钱包，确认仍能访问。验证恢复完成前，保留旧设备和独立备份。","如果任何检查未通过，请保留原钱包并联系客服。不要为了修复恢复问题而追加资金或创建新钱包。"]}},"nav":"恢复钱包访问"},"vi":{"name":"Tiếng Việt","title":"Passkey: đổi thiết bị và khôi phục ví","intro":"Mở wallet.getyoursats.com trong trình duyệt đầy đủ và chọn Restore cho ví hiện có. Dùng passkey gốc và cùng nhãn ví nếu được hỏi. Chọn Start hoặc tạo passkey mới có thể tạo một ví khác.","safety":"Giữ thiết bị cũ, passkey và dữ liệu ví cho đến khi xác minh khôi phục thành công. Tìm thấy passkey hoặc đăng nhập được không chứng minh đã khôi phục đúng ví. Tên menu có thể khác theo phiên bản hệ thống.","language":"Ngôn ngữ hướng dẫn","source":"Hướng dẫn chính thức của nền tảng","contact":"Vẫn gặp vấn đề? Gửi bộ phận hỗ trợ loại thiết bị, phiên bản hệ điều hành và trình duyệt, URL ví, lỗi và việc passkey có xuất hiện không. Không gửi cụm từ khôi phục, khóa, PIN hay bí mật passkey.","scenarios":{"google-to-iphone":{"title":"Passkey Google: Android → iPhone","steps":["Cài và mở Chrome trên iPhone. Đăng nhập tài khoản Google lưu passkey gốc. Chỉ có ứng dụng tìm kiếm Google không đồng nghĩa với Chrome hoặc nhà cung cấp passkey của Chrome.","Trên iOS 17 trở lên, tìm Tự động điền & Mật khẩu trong Cài đặt. Bật Chrome làm nhà cung cấp mật khẩu và passkey.","Mở ví trong Chrome và chọn Restore. Khi được yêu cầu, mở khóa Trình quản lý mật khẩu Google bằng PIN hoặc khóa màn hình thiết bị cũ được chỉ định. Chọn passkey hiện có."]},"google-to-android":{"title":"Passkey Google: iPhone hoặc Android → Android","steps":["Chỉ dùng cách này nếu passkey gốc nằm trong Trình quản lý mật khẩu Google, kể cả passkey tạo bằng Chrome trên iPhone.","Trên Android mới, đăng nhập cùng tài khoản Google và bật Trình quản lý mật khẩu Google cho mật khẩu/passkey trong Cài đặt. Đợi đồng bộ và mở khóa khi được yêu cầu.","Mở đúng trang ví trong Chrome, chọn Restore và passkey gốc. Đăng nhập Google không làm passkey trong Mật khẩu Apple xuất hiện."]},"apple-to-apple":{"title":"Mật khẩu Apple: iPhone → iPhone hoặc iPad","steps":["Đăng nhập cùng Tài khoản Apple trên thiết bị mới. Bật đồng bộ Mật khẩu & Chuỗi khóa trong iCloud và hoàn tất các yêu cầu khôi phục tài khoản.","Bật Mật khẩu Apple cho tính năng tự động điền và kiểm tra có passkey của ví.","Mở trang ví gốc trong Safari, chọn Restore và passkey đó."]},"apple-to-android-qr":{"title":"Mật khẩu Apple → Android khi vẫn có iPhone bên cạnh","steps":["Mở ví trên Android và chọn Restore. Nếu có, chọn dùng passkey từ điện thoại hoặc máy tính bảng khác.","Để hai thiết bị gần nhau, bật Bluetooth và internet. Dùng iPhone chứa passkey gốc quét mã QR hiển thị và phê duyệt trên iPhone đó.","Cách này dùng thông tin xác thực trên iPhone, không sao chép sang Android. Khôi phục ví qua cách này chưa được xác minh. Nếu không có hoặc không hỗ trợ, hãy dừng và giữ ví đang hoạt động."]},"move-provider":{"title":"Chuyển giữa Mật khẩu Apple và Trình quản lý mật khẩu Google","steps":["Đây là tùy chọn chuyển dữ liệu của nền tảng, chưa phải cách khôi phục GetYourSats đã xác minh. Chuyển passkey có thể không giữ được bí mật cần để mở đúng ví. Giữ thông tin xác thực và thiết bị gốc.","Nếu cả hai ứng dụng hỗ trợ chuyển passkey an toàn, dùng tùy chọn chuyển/xuất của ứng dụng nguồn và chọn ứng dụng đích. Để nhập vào Google trên iPhone, chọn Chrome rồi xác thực để hoàn tất. CSV mật khẩu không phải bản sao lưu passkey.","Đồng bộ ứng dụng đích với thiết bị mới rồi kiểm tra ví theo danh sách bên dưới. Nếu không thể chuyển, dùng thiết bị tương thích hiện có hoặc bản sao lưu độc lập đã xác minh cho đúng ví này."]},"missing-passkey":{"title":"Không thấy passkey hoặc đăng nhập bị hủy","steps":["Mở chính xác trang ví gốc trong trình duyệt đầy đủ, không dùng ứng dụng tìm kiếm Google hoặc trình duyệt trong ứng dụng. Kiểm tra trình quản lý, tài khoản, đồng bộ và nhà cung cấp tự động điền. Cập nhật trình duyệt và hệ điều hành.","Chọn lại Restore và hoàn tất lời nhắc hệ thống. Thông báo hủy cũng có thể do không có thông tin xác thực phù hợp, hết thời gian hoặc nhà cung cấp không khả dụng; không chứng minh bạn đã hủy.","Nếu thấy passkey nhưng ví không mở, nhà cung cấp có thể thiếu tính năng mật mã mà ví cần. Giữ ví gốc; không tạo passkey thay thế hoặc xóa dữ liệu để khắc phục. Liên hệ hỗ trợ."]},"lost-device":{"title":"Điện thoại cũ bị mất, hỏng hoặc đã xóa","steps":["Trước tiên khôi phục tài khoản trình quản lý mật khẩu gốc và passkey đã đồng bộ trên thiết bị tương thích. Mật khẩu Apple không tự đồng bộ sang Android. Đăng nhập QR cần thiết bị khả dụng đang giữ passkey.","Nếu không thể, chỉ dùng bản sao lưu khôi phục độc lập đã được xác minh cho đúng ví này. Cụm từ của ví khác không khôi phục được số tiền này.","Không có passkey gốc tương thích hoặc bản sao lưu đã xác minh thì hỗ trợ, xác minh email và tên Lightning không thể tạo lại khóa ví. Không xóa dữ liệu ví còn lại."]},"verify-wallet":{"title":"Trước khi xóa hoặc thay thiết bị cũ","steps":["So sánh danh tính ví, số dư và lịch sử thanh toán sau khôi phục với ví gốc. Chỉ nhãn ví không đủ. Dừng nếu khác nhau hoặc xuất hiện ví trống ngoài dự kiến.","Đóng rồi mở lại ví trên thiết bị mới để kiểm tra vẫn truy cập được. Giữ thiết bị cũ và bản sao lưu độc lập đến khi xác minh khôi phục.","Nếu bất kỳ bước kiểm tra nào không đạt, giữ nguyên ví gốc và liên hệ hỗ trợ. Không gửi thêm tiền hoặc tạo ví mới để sửa lỗi khôi phục."]}},"nav":"Khôi phục quyền truy cập ví"},"ar":{"name":"العربية","title":"مفاتيح المرور: تغيير الجهاز واستعادة محفظتك","intro":"افتح wallet.getyoursats.com في متصفح كامل واختر Restore لمحفظتك الحالية. استخدم مفتاح المرور الأصلي ونفس تسمية المحفظة إن طُلبت. قد يؤدي اختيار Start أو إنشاء مفتاح مرور جديد إلى إنشاء محفظة مختلفة.","safety":"احتفظ بالجهاز القديم ومفتاح المرور وبيانات المحفظة حتى تتحقق من الاستعادة. ظهور مفتاح المرور أو نجاح تسجيل الدخول لا يثبت استعادة المحفظة نفسها. تختلف أسماء القوائم حسب إصدار النظام.","language":"لغة الدليل","source":"تعليمات المنصات الرسمية","contact":"ما زلت تواجه مشكلة؟ أخبر الدعم بالجهاز وإصدارات النظام والمتصفح ورابط المحفظة ونص الخطأ وما إذا ظهر مفتاح المرور. لا ترسل كلمات الاستعادة أو المفاتيح أو رموز PIN أو أسرار مفتاح المرور.","scenarios":{"google-to-iphone":{"title":"مفتاح مرور Google: من Android إلى iPhone","steps":["ثبّت Chrome وافتحه على iPhone وسجّل الدخول إلى حساب Google الذي يحفظ مفتاح المرور الأصلي. تطبيق بحث Google وحده ليس Chrome ولا موفّر مفاتيح المرور الخاص به.","في iOS 17 أو أحدث، ابحث في الإعدادات عن التعبئة التلقائية وكلمات السر. فعّل Chrome كموفّر لكلمات السر ومفاتيح المرور.","افتح المحفظة في Chrome واختر Restore. إذا طُلب ذلك، افتح مدير كلمات المرور في Google باستخدام رمز PIN الخاص به أو قفل شاشة الجهاز السابق المطلوب. اختر مفتاح المرور الموجود."]},"google-to-android":{"title":"مفتاح مرور Google: من iPhone أو Android إلى Android","steps":["استخدم هذا المسار فقط إذا كان مفتاح المرور الأصلي محفوظًا في مدير كلمات المرور في Google، بما فيه المفتاح الذي أُنشئ على iPhone باستخدام Chrome.","على جهاز Android الجديد، سجّل الدخول إلى حساب Google نفسه وفعّل مدير كلمات المرور في Google لكلمات السر ومفاتيح المرور في الإعدادات. انتظر المزامنة وافتح المدير عندما يُطلب منك ذلك.","افتح موقع المحفظة نفسه في Chrome واختر Restore ثم مفتاح المرور الأصلي. تسجيل الدخول إلى Google لا يُظهر مفتاح مرور محفوظًا في تطبيق كلمات السر من Apple تلقائيًا."]},"apple-to-apple":{"title":"كلمات السر من Apple: من iPhone إلى iPhone أو iPad","steps":["سجّل الدخول إلى حساب Apple نفسه على الجهاز الجديد. فعّل مزامنة كلمات السر وسلسلة المفاتيح في إعدادات iCloud وأكمل طلبات استرداد الحساب.","فعّل كلمات السر من Apple للتعبئة التلقائية وتحقق من وجود مفتاح مرور المحفظة في التطبيق.","افتح موقع المحفظة الأصلي في Safari واختر Restore ثم مفتاح المرور نفسه."]},"apple-to-android-qr":{"title":"كلمات السر من Apple إلى Android مع وجود iPhone بالقرب منك","steps":["افتح المحفظة على Android واختر Restore. اختر استخدام مفتاح مرور من هاتف أو جهاز لوحي آخر إذا كان الخيار متاحًا.","ضع الجهازين بالقرب من بعضهما مع تفعيل Bluetooth والإنترنت. امسح رمز QR المعروض باستخدام iPhone الذي يحمل المفتاح الأصلي ووافق على ذلك الهاتف.","يستخدم هذا بيانات الاعتماد الموجودة على iPhone ولا ينسخها إلى Android. لم تُتحقق بعد استعادة المحفظة بهذا المسار. إن لم يكن متاحًا أو مدعومًا، توقف واحتفظ بالمحفظة التي تعمل."]},"move-provider":{"title":"الانتقال بين كلمات السر من Apple ومدير كلمات المرور في Google","steps":["هذا خيار نقل توفره المنصة وليس مسار استعادة موثّقًا لـ GetYourSats. قد لا يحافظ نقل مفتاح المرور على السر اللازم لفتح المحفظة نفسها. احتفظ ببيانات الاعتماد والجهاز الأصليين.","إذا كان التطبيقان يقدّمان نقلًا آمنًا لمفاتيح المرور، استخدم خيار النقل أو التصدير في المدير الأصلي واختر المدير الوجهة. للاستيراد إلى Google على iPhone، اختر Chrome وأكمل المصادقة. ملف CSV لكلمات السر ليس نسخة احتياطية لمفتاح المرور.","زامن المدير الوجهة على الجهاز الجديد ثم تحقق من المحفظة وفق القائمة أدناه. إذا تعذر النقل، استخدم جهازًا متوافقًا موجودًا أو نسخة احتياطية مستقلة سبق التحقق منها لهذه المحفظة بالذات."]},"missing-passkey":{"title":"لا يظهر مفتاح مرور أو يُلغى تسجيل الدخول","steps":["افتح عنوان موقع المحفظة الأصلي بالضبط في متصفح كامل، خارج تطبيق بحث Google أو المتصفح المدمج داخل تطبيق. تحقق من المدير والحساب والمزامنة وموفّر التعبئة التلقائية. حدّث المتصفح والنظام.","اختر Restore مجددًا وأكمل طلب النظام. قد تعني رسالة الإلغاء أيضًا عدم وجود بيانات اعتماد مطابقة أو انتهاء المهلة أو تعذر الوصول إلى الموفّر؛ وهي لا تثبت أنك ألغيت العملية.","إذا ظهر المفتاح لكن لم تُفتح المحفظة، فقد يفتقر الموفّر إلى الدعم التشفيري المطلوب. احتفظ بالمحفظة الأصلية ولا تنشئ مفتاحًا بديلًا أو تمسح البيانات لحل المشكلة. تواصل مع الدعم."]},"lost-device":{"title":"فُقد الهاتف القديم أو تعطل أو مُسحت بياناته","steps":["استعد أولًا الوصول إلى حساب مدير كلمات المرور الأصلي ومفاتيحه المتزامنة على جهاز متوافق. كلمات السر من Apple لا تتزامن تلقائيًا مع Android. يتطلب تسجيل الدخول برمز QR جهازًا متاحًا يحمل المفتاح.","إذا تعذر ذلك، استخدم فقط نسخة استعادة مستقلة سبق التحقق منها لهذه المحفظة بالذات. عبارة استعادة محفظة أخرى لن تستعيد هذه الأموال.","من دون مفتاح المرور الأصلي المتوافق أو نسخة احتياطية موثّقة، لا يستطيع الدعم أو التحقق بالبريد أو اسم Lightning إعادة إنشاء مفاتيح المحفظة. لا تمسح أي بيانات محفظة متبقية."]},"verify-wallet":{"title":"قبل مسح الجهاز القديم أو استبداله","steps":["قارن هوية المحفظة المستعادة ورصيدها وسجل مدفوعاتها بالأصل. تسمية المحفظة وحدها لا تكفي. توقف إذا اختلفت أو ظهرت محفظة فارغة على غير المتوقع.","أغلق المحفظة وأعد فتحها على الجهاز الجديد للتحقق من استمرار الوصول. احتفظ بالجهاز القديم والنسخة المستقلة حتى تتحقق الاستعادة.","إذا فشل أي تحقق، احتفظ بالمحفظة الأصلية دون تغيير وتواصل مع الدعم. لا ترسل أموالًا إضافية ولا تنشئ محفظة جديدة لحل مشكلة الاستعادة."]}},"nav":"استعادة الوصول إلى المحفظة"},"th":{"name":"ไทย","title":"พาสคีย์: เปลี่ยนอุปกรณ์และกู้คืนกระเป๋า","intro":"เปิด wallet.getyoursats.com ในเบราว์เซอร์เต็มรูปแบบ แล้วเลือก Restore สำหรับกระเป๋าเดิม ใช้พาสคีย์เดิมและชื่อกระเป๋าเดิมหากระบบถาม การเลือก Start หรือสร้างพาสคีย์ใหม่อาจสร้างกระเป๋าคนละใบ","safety":"เก็บอุปกรณ์เก่า พาสคีย์ และข้อมูลกระเป๋าไว้จนกว่าจะตรวจสอบการกู้คืนแล้ว การพบพาสคีย์หรือเข้าสู่ระบบสำเร็จไม่ได้ยืนยันว่ากู้คืนกระเป๋าเดิมได้ ชื่อเมนูอาจต่างกันตามรุ่นระบบ","language":"ภาษาของคู่มือ","source":"คำแนะนำอย่างเป็นทางการของแพลตฟอร์ม","contact":"ยังมีปัญหาอยู่? แจ้งฝ่ายสนับสนุนเรื่องอุปกรณ์ รุ่นระบบและเบราว์เซอร์ URL กระเป๋า ข้อความผิดพลาด และพบพาสคีย์หรือไม่ ห้ามส่งคำกู้คืน กุญแจ PIN หรือข้อมูลลับของพาสคีย์","scenarios":{"google-to-iphone":{"title":"พาสคีย์ Google: Android → iPhone","steps":["ติดตั้งและเปิด Chrome บน iPhone ลงชื่อเข้าใช้บัญชี Google ที่เก็บพาสคีย์เดิม แอปค้นหา Google เพียงอย่างเดียวไม่ใช่ Chrome หรือผู้ให้บริการพาสคีย์ของ Chrome","บน iOS 17 ขึ้นไป ค้นหาการป้อนอัตโนมัติและรหัสผ่านในแอปการตั้งค่า แล้วเปิดใช้ Chrome เป็นผู้ให้บริการรหัสผ่านและพาสคีย์","เปิดกระเป๋าใน Chrome แล้วเลือก Restore หากระบบขอ ให้ปลดล็อกเครื่องมือจัดการรหัสผ่าน Google ด้วย PIN หรือรหัสล็อกหน้าจอของอุปกรณ์เก่าที่ระบบระบุ แล้วเลือกพาสคีย์เดิม"]},"google-to-android":{"title":"พาสคีย์ Google: iPhone หรือ Android → Android","steps":["ใช้วิธีนี้เมื่อพาสคีย์เดิมอยู่ในเครื่องมือจัดการรหัสผ่าน Google เท่านั้น รวมถึงพาสคีย์ที่สร้างผ่าน Chrome บน iPhone","บน Android เครื่องใหม่ ลงชื่อเข้าใช้บัญชี Google เดิม และเปิดใช้เครื่องมือจัดการรหัสผ่าน Google สำหรับรหัสผ่านและพาสคีย์ในการตั้งค่า รอการซิงค์และปลดล็อกเมื่อระบบขอ","เปิดเว็บไซต์กระเป๋าเดิมใน Chrome เลือก Restore และพาสคีย์เดิม การลงชื่อเข้าใช้ Google ไม่ทำให้พาสคีย์ในแอปรหัสผ่านของ Apple ปรากฏขึ้นเอง"]},"apple-to-apple":{"title":"แอปรหัสผ่านของ Apple: iPhone → iPhone หรือ iPad","steps":["ลงชื่อเข้าใช้บัญชี Apple เดิมบนเครื่องใหม่ เปิดการซิงค์รหัสผ่านและพวงกุญแจใน iCloud และทำขั้นตอนกู้คืนบัญชีตามที่ระบบขอ","เปิดใช้แอปรหัสผ่านของ Apple สำหรับการป้อนอัตโนมัติ และตรวจว่ามีพาสคีย์ของกระเป๋าอยู่","เปิดเว็บไซต์กระเป๋าเดิมใน Safari เลือก Restore และพาสคีย์นั้น"]},"apple-to-android-qr":{"title":"แอปรหัสผ่านของ Apple → Android เมื่อมี iPhone อยู่ใกล้","steps":["เปิดกระเป๋าบน Android แล้วเลือก Restore หากมีตัวเลือก ให้เลือกใช้พาสคีย์จากโทรศัพท์หรือแท็บเล็ตเครื่องอื่น","วางทั้งสองเครื่องไว้ใกล้กัน เปิด Bluetooth และอินเทอร์เน็ต ใช้ iPhone ที่เก็บพาสคีย์เดิมสแกน QR ที่แสดง แล้วอนุมัติบน iPhone เครื่องนั้น","วิธีนี้ใช้ข้อมูลยืนยันตัวตนบน iPhone ไม่ได้คัดลอกไป Android การกู้คืนกระเป๋าผ่านวิธีนี้ยังไม่ได้รับการยืนยัน หากใช้ไม่ได้หรือไม่รองรับ ให้หยุดและเก็บกระเป๋าที่ยังใช้งานได้ไว้"]},"move-provider":{"title":"ย้ายระหว่างแอปรหัสผ่านของ Apple กับเครื่องมือจัดการรหัสผ่าน Google","steps":["นี่คือตัวเลือกย้ายข้อมูลของแพลตฟอร์ม ไม่ใช่วิธีกู้คืน GetYourSats ที่ผ่านการยืนยัน การย้ายพาสคีย์อาจไม่รักษาข้อมูลลับที่ใช้เปิดกระเป๋าเดิม เก็บข้อมูลยืนยันตัวตนและอุปกรณ์เดิมไว้","หากทั้งสองแอปรองรับการโอนพาสคีย์อย่างปลอดภัย ให้ใช้ตัวเลือกโอนหรือส่งออกในแอปต้นทาง แล้วเลือกแอปปลายทาง หากนำเข้า Google บน iPhone ให้เลือก Chrome และยืนยันตัวตนจนเสร็จ ไฟล์ CSV ของรหัสผ่านไม่ใช่ข้อมูลสำรองพาสคีย์","ซิงค์แอปปลายทางบนเครื่องใหม่ แล้วตรวจสอบกระเป๋าตามรายการด้านล่าง หากโอนไม่ได้ ให้ใช้อุปกรณ์เดิมที่รองรับ หรือข้อมูลสำรองอิสระที่ตรวจสอบแล้วว่าใช้กับกระเป๋าใบนี้ได้"]},"missing-passkey":{"title":"ไม่พบพาสคีย์ หรือการเข้าสู่ระบบถูกยกเลิก","steps":["เปิด URL กระเป๋าเดิมให้ตรงทุกส่วนในเบราว์เซอร์เต็มรูปแบบ ไม่ใช้แอปค้นหา Google หรือเบราว์เซอร์ภายในแอป ตรวจแอปจัดการรหัสผ่าน บัญชี การซิงค์ และผู้ให้บริการป้อนอัตโนมัติ อัปเดตเบราว์เซอร์และระบบ","เลือก Restore อีกครั้งและทำตามหน้าต่างของระบบ ข้อความยกเลิกอาจหมายถึงไม่พบข้อมูลยืนยันตัวตนที่ตรงกัน หมดเวลา หรือผู้ให้บริการไม่พร้อม ไม่ได้ยืนยันว่าคุณกดยกเลิกเอง","หากพบพาสคีย์แต่เปิดกระเป๋าไม่ได้ ผู้ให้บริการอาจไม่มีความสามารถด้านการเข้ารหัสที่กระเป๋าต้องใช้ เก็บกระเป๋าเดิมไว้ อย่าสร้างพาสคีย์แทนหรือเคลียร์ข้อมูลเพื่อแก้ปัญหา ให้ติดต่อฝ่ายสนับสนุน"]},"lost-device":{"title":"โทรศัพท์เก่าหาย เสีย หรือล้างข้อมูลไปแล้ว","steps":["ก่อนอื่น กู้คืนบัญชีแอปจัดการรหัสผ่านเดิมและพาสคีย์ที่ซิงค์ไว้บนอุปกรณ์ที่รองรับ แอปรหัสผ่านของ Apple ไม่ซิงค์กับ Android อัตโนมัติ การเข้าสู่ระบบด้วย QR ต้องมีอุปกรณ์ที่ยังใช้งานได้และเก็บพาสคีย์นั้น","หากทำไม่ได้ ให้ใช้เฉพาะข้อมูลสำรองสำหรับกู้คืนแบบอิสระที่เคยตรวจสอบแล้วว่าเป็นของกระเป๋าใบนี้ คำกู้คืนของกระเป๋าอื่นจะไม่กู้เงินนี้","หากไม่มีพาสคีย์เดิมที่รองรับหรือข้อมูลสำรองที่ตรวจสอบแล้ว ฝ่ายสนับสนุน การยืนยันอีเมล และชื่อ Lightning ไม่สามารถสร้างกุญแจกระเป๋ากลับมาได้ อย่าลบข้อมูลกระเป๋าที่ยังเหลือ"]},"verify-wallet":{"title":"ก่อนล้างข้อมูลหรือเปลี่ยนอุปกรณ์เก่า","steps":["เปรียบเทียบตัวตนกระเป๋า ยอดเงิน และประวัติการชำระเงินที่กู้คืนกับกระเป๋าเดิม ชื่อกระเป๋าอย่างเดียวไม่พอ หากไม่ตรงกันหรือพบกระเป๋าว่างโดยไม่คาดคิด ให้หยุด","ปิดและเปิดกระเป๋าบนเครื่องใหม่อีกครั้งเพื่อตรวจว่ายังเข้าได้ เก็บเครื่องเก่าและข้อมูลสำรองอิสระไว้จนกว่าจะตรวจสอบการกู้คืนสำเร็จ","หากตรวจสอบข้อใดไม่ผ่าน ให้เก็บกระเป๋าเดิมไว้โดยไม่เปลี่ยนแปลงและติดต่อฝ่ายสนับสนุน อย่าส่งเงินเพิ่มหรือสร้างกระเป๋าใหม่เพื่อแก้ปัญหาการกู้คืน"]}},"nav":"กู้คืนการเข้าถึงกระเป๋า"},"ta":{"name":"தமிழ்","title":"பாஸ்கீ: சாதனத்தை மாற்றி உங்கள் பணப்பையை மீட்டெடுக்கவும்","intro":"முழுமையான உலாவியில் wallet.getyoursats.com திறந்து, ஏற்கெனவே உள்ள பணப்பைக்கு Restore தேர்ந்தெடுக்கவும். அசல் பாஸ்கீயையும், கேட்டால் அதே பணப்பைப் பெயரையும் பயன்படுத்தவும். Start அல்லது புதிய பாஸ்கீ வேறொரு பணப்பையை உருவாக்கலாம்.","safety":"மீட்பைச் சரிபார்க்கும் வரை பழைய சாதனம், பாஸ்கீ மற்றும் பணப்பைத் தரவைப் பாதுகாக்கவும். பாஸ்கீ தெரிவது அல்லது உள்நுழைவு முடிவது மட்டும் அதே பணப்பை மீண்டதற்கான சான்றல்ல. மெனுப் பெயர்கள் கணினி அமைப்பின் பதிப்பைப் பொறுத்து மாறலாம்.","language":"வழிகாட்டியின் மொழி","source":"தளங்களின் அதிகாரப்பூர்வ வழிமுறைகள்","contact":"இன்னும் சிக்கலா? சாதனம், இயங்குதளம் மற்றும் உலாவிப் பதிப்புகள், பணப்பை URL, பிழைச் செய்தி, பாஸ்கீ தெரிந்ததா ஆகியவற்றை ஆதரவுக் குழுவிடம் தெரிவிக்கவும். மீட்பு வார்த்தைகள், விசைகள், PIN அல்லது பாஸ்கீ ரகசியங்களை அனுப்ப வேண்டாம்.","scenarios":{"google-to-iphone":{"title":"Google பாஸ்கீ: Android → iPhone","steps":["iPhone-இல் Chrome நிறுவித் திறக்கவும். அசல் பாஸ்கீ உள்ள Google கணக்கில் உள்நுழையவும். Google தேடல் செயலி மட்டும் Chrome அல்லது அதன் பாஸ்கீ வழங்குநர் அல்ல.","iOS 17 அல்லது அதற்குப் பிந்தைய பதிப்பில் Settings-இல் AutoFill & Passwords தேடவும். கடவுச்சொல் மற்றும் பாஸ்கீ வழங்குநராக Chrome-ஐ இயக்கவும்.","Chrome-இல் பணப்பையைத் திறந்து Restore தேர்ந்தெடுக்கவும். கேட்டால் Google Password Manager PIN அல்லது குறிப்பிடப்பட்ட பழைய சாதனத்தின் திரைப் பூட்டை உள்ளிட்டு திறக்கவும். ஏற்கெனவே உள்ள பாஸ்கீயைத் தேர்ந்தெடுக்கவும்."]},"google-to-android":{"title":"Google பாஸ்கீ: iPhone அல்லது Android → Android","steps":["அசல் பாஸ்கீ Google Password Manager-இல் இருந்தால் மட்டுமே இந்த முறையைப் பயன்படுத்தவும். iPhone-இல் Chrome மூலம் உருவாக்கிய பாஸ்கீயும் இதில் அடங்கும்.","புதிய Android-இல் அதே Google கணக்கில் உள்நுழைந்து, Settings-இல் கடவுச்சொல்/பாஸ்கீக்கு Google Password Manager-ஐ இயக்கவும். ஒத்திசைவு முடியும் வரை காத்திருந்து, கேட்டால் திறக்கவும்.","Chrome-இல் அதே பணப்பை இணையதளத்தைத் திறந்து Restore மற்றும் அசல் பாஸ்கீயைத் தேர்ந்தெடுக்கவும். Google-இல் உள்நுழைவதால் மட்டும் Apple Passwords பாஸ்கீ தோன்றாது."]},"apple-to-apple":{"title":"Apple Passwords: iPhone → iPhone அல்லது iPad","steps":["புதிய சாதனத்தில் அதே Apple Account-இல் உள்நுழையவும். iCloud அமைப்புகளில் Passwords & Keychain ஒத்திசைவை இயக்கி, கணக்கு மீட்புக் கோரிக்கைகளை முடிக்கவும்.","AutoFill-க்கு Apple Passwords-ஐ இயக்கி, பணப்பையின் பாஸ்கீ அங்கு இருப்பதைச் சரிபார்க்கவும்.","Safari-இல் அசல் பணப்பை இணையதளத்தைத் திறந்து Restore மற்றும் அதே பாஸ்கீயைத் தேர்ந்தெடுக்கவும்."]},"apple-to-android-qr":{"title":"Apple Passwords → Android, iPhone அருகில் இருக்கும்போது","steps":["Android-இல் பணப்பையைத் திறந்து Restore தேர்ந்தெடுக்கவும். கிடைத்தால் வேறொரு தொலைபேசி அல்லது டேப்லெட்டின் பாஸ்கீயைப் பயன்படுத்தும் விருப்பத்தைத் தேர்ந்தெடுக்கவும்.","இரண்டு சாதனங்களையும் அருகில் வைத்து Bluetooth மற்றும் இணையத்தை இயக்கவும். அசல் பாஸ்கீ உள்ள iPhone மூலம் காட்டப்படும் QR குறியீட்டை ஸ்கேன் செய்து, அதே iPhone-இல் அனுமதிக்கவும்.","இது iPhone-இல் உள்ள சான்றைப் பயன்படுத்தும்; Android-க்கு நகலெடுக்காது. இந்த முறையில் பணப்பை மீட்பு இன்னும் சரிபார்க்கப்படவில்லை. விருப்பம் கிடைக்கவில்லை அல்லது ஆதரிக்கப்படவில்லை என்றால் நிறுத்தி, இயங்கும் பணப்பையைப் பாதுகாக்கவும்."]},"move-provider":{"title":"Apple Passwords மற்றும் Google Password Manager இடையே மாற்றுதல்","steps":["இது தளம் வழங்கும் மாற்று வசதி; சரிபார்க்கப்பட்ட GetYourSats மீட்பு முறை அல்ல. பாஸ்கீ மாற்றம் அதே பணப்பையைத் திறக்கத் தேவையான ரகசியத்தைப் பாதுகாக்காமல் போகலாம். அசல் சான்றையும் சாதனத்தையும் வைத்திருக்கவும்.","இரு செயலிகளும் பாதுகாப்பான பாஸ்கீ மாற்றத்தை வழங்கினால், மூல மேலாளரின் மாற்று/ஏற்றுமதி விருப்பத்தைப் பயன்படுத்தி இலக்கு மேலாளரைத் தேர்ந்தெடுக்கவும். iPhone-இல் Google-க்கு இறக்குமதி செய்ய Chrome தேர்ந்தெடுத்து அங்கீகாரத்தை முடிக்கவும். கடவுச்சொல் CSV என்பது பாஸ்கீ காப்புப்பிரதி அல்ல.","புதிய சாதனத்தில் இலக்கு மேலாளரை ஒத்திசைத்து, கீழுள்ள பட்டியலின்படி பணப்பையைச் சரிபார்க்கவும். மாற்ற முடியவில்லை என்றால், ஏற்கெனவே உள்ள இணக்கமான சாதனம் அல்லது இதே பணப்பைக்கு தனியாகச் சரிபார்க்கப்பட்ட காப்புப்பிரதியைப் பயன்படுத்தவும்."]},"missing-passkey":{"title":"பாஸ்கீ தெரியவில்லை அல்லது உள்நுழைவு ரத்தாகிறது","steps":["Google தேடல் செயலி அல்லது செயலிக்குள் உள்ள உலாவிக்கு வெளியே, முழுமையான உலாவியில் அசல் பணப்பை இணையதளத்தைத் துல்லியமாகத் திறக்கவும். மேலாளர், கணக்கு, ஒத்திசைவு மற்றும் AutoFill வழங்குநரைச் சரிபார்க்கவும். உலாவி மற்றும் இயங்குதளத்தைப் புதுப்பிக்கவும்.","Restore மீண்டும் தேர்ந்தெடுத்து கணினி அமைப்பின் கோரிக்கையை முடிக்கவும். பொருந்தும் சான்று இல்லாமை, நேரம் முடிவடைதல் அல்லது வழங்குநர் கிடைக்காமையும் ரத்துச் செய்தியை ஏற்படுத்தலாம்; நீங்கள் ரத்து செய்தீர்கள் என்பதற்குச் சான்றல்ல.","பாஸ்கீ தெரிந்தும் பணப்பை திறக்கவில்லை என்றால், வழங்குநரில் தேவையான குறியாக்க ஆதரவு இல்லாமல் இருக்கலாம். அசல் பணப்பையைப் பாதுகாக்கவும்; இதைச் சரிசெய்ய மாற்றுப் பாஸ்கீ உருவாக்கவோ தரவை அழிக்கவோ வேண்டாம். ஆதரவைக் தொடர்புகொள்ளவும்."]},"lost-device":{"title":"பழைய தொலைபேசி தொலைந்தது, பழுதானது அல்லது அழிக்கப்பட்டது","steps":["முதலில் இணக்கமான சாதனத்தில் அசல் கடவுச்சொல் மேலாளர் கணக்கையும் ஒத்திசைந்த பாஸ்கீகளையும் மீட்டெடுக்கவும். Apple Passwords தானாக Android-உடன் ஒத்திசையாது. QR உள்நுழைவுக்கு பாஸ்கீ உள்ள, பயன்படுத்தக்கூடிய சாதனம் தேவை.","அது முடியவில்லை என்றால், இதே பணப்பைக்காக ஏற்கெனவே சரிபார்க்கப்பட்ட தனி மீட்புக் காப்புப்பிரதியை மட்டும் பயன்படுத்தவும். வேறொரு பணப்பையின் மீட்பு வார்த்தைகள் இந்த நிதியை மீட்காது.","இணக்கமான அசல் பாஸ்கீ அல்லது சரிபார்க்கப்பட்ட காப்புப்பிரதி இல்லாமல், ஆதரவு, மின்னஞ்சல் சரிபார்ப்பு அல்லது Lightning பெயர் பணப்பை விசைகளை மீண்டும் உருவாக்க முடியாது. மீதமுள்ள பணப்பைத் தரவை அழிக்க வேண்டாம்."]},"verify-wallet":{"title":"பழைய சாதனத்தை அழிக்கும் அல்லது மாற்றும் முன்","steps":["மீட்டெடுத்த பணப்பையின் அடையாளம், இருப்பு மற்றும் கட்டண வரலாற்றை அசலுடன் ஒப்பிடவும். பணப்பைப் பெயர் மட்டும் சான்றல்ல. வேறுபட்டால் அல்லது எதிர்பாராத காலிப் பணப்பை தோன்றினால் நிறுத்தவும்.","புதிய சாதனத்தில் பணப்பையை மூடி மீண்டும் திறந்து அணுகல் தொடர்கிறதா எனப் பார்க்கவும். மீட்பு சரிபார்க்கப்படும் வரை பழைய சாதனத்தையும் தனிக் காப்புப்பிரதியையும் வைத்திருக்கவும்.","ஏதேனும் சரிபார்ப்பு தோல்வியடைந்தால், அசல் பணப்பையை மாற்றாமல் வைத்து ஆதரவைக் தொடர்புகொள்ளவும். மீட்புச் சிக்கலைச் சரிசெய்ய மேலும் நிதி அனுப்பவோ புதிய பணப்பை உருவாக்கவோ வேண்டாம்."]}},"nav":"பணப்பை அணுகலை மீட்டெடுக்கவும்"}};
const PASSKEY_SUPPORT_SOURCES = [["Google · iPhone","https://support.google.com/chrome/answer/13168025?co=GENIE.Platform%3DiOS"],["Google · Android","https://developers.google.com/identity/passkeys/supported-environments"],["Apple","https://support.apple.com/guide/iphone/use-passkeys-to-sign-in-to-apps-and-websites-iphf538ea8d0/ios"],["Apple ↔ Google","https://support.google.com/chrome/answer/13068232?co=GENIE.Platform%3DiOS"]];
// Appended to the generated locale catalog by generate-passkey-guide.mjs.
(() => {
  'use strict';
  const section = document.getElementById('section-1');
  const select = document.getElementById('gys-language');
  if (!section || !select) return;
  const copies = PASSKEY_SUPPORT_COPY;
  const node = (tag, text) => {
    const element = document.createElement(tag);
    if (text !== undefined) element.textContent = text;
    return element;
  };
  for (const [code, copy] of Object.entries(copies)) {
    if (!Array.from(select.options).some(option => option.value === code)) {
      select.add(new Option(copy.name, code));
    }
  }
  function revealHash(scroll = false) {
    const target = document.getElementById(location.hash.slice(1));
    if (target && section.contains(target) && target.tagName === 'DETAILS') {
      target.open = true;
      if (scroll) target.scrollIntoView({ block: 'start' });
    }
  }
  function render(code) {
    const language = Object.hasOwn(copies, code) ? code : 'en';
    const copy = copies[language];
    const previouslyOpen = new Set(Array.from(section.querySelectorAll('details[open]'), el => el.id));
    section.lang = language;
    section.dir = language === 'ar' ? 'rtl' : 'ltr';
    section.replaceChildren();
    const heading = node('h2', copy.title);
    heading.id = 'passkey-guide-title';
    section.append(heading, node('p', copy.intro));
    const safety = node('p', copy.safety);
    safety.className = 'note';
    section.append(safety);
    for (const [id, scenario] of Object.entries(copy.scenarios)) {
      const detail = node('details');
      detail.id = `passkey-${id}`;
      detail.className = 'gys-passkey-case';
      detail.open = previouslyOpen.has(detail.id);
      detail.append(node('summary', scenario.title));
      const list = node('ol');
      for (const step of scenario.steps) list.append(node('li', step));
      detail.append(list);
      section.append(detail);
    }
    const contact = node('p');
    const link = node('a', copy.contact);
    link.href = '#contact';
    contact.append(link);
    section.append(contact);
    const sources = node('p', copy.source + ': ');
    PASSKEY_SUPPORT_SOURCES.forEach(([label, href], index) => {
      if (index) sources.append(document.createTextNode(' · '));
      const link = node('a', label);
      link.href = href;
      link.rel = 'noopener noreferrer';
      sources.append(link);
    });
    section.append(sources);
    document.querySelectorAll('a[href="#section-1"]').forEach(link => { link.textContent = copy.nav; });
    select.value = language;
    select.setAttribute('aria-label', copy.language);
    revealHash();
  }
  function storedLanguage() {
    try { return localStorage.getItem('gys:language:v1') || localStorage.getItem('gys:help-lang'); }
    catch { return null; }
  }
  function deviceLanguage() {
    for (const raw of navigator.languages || []) {
      const code = raw.toLowerCase();
      if (code === 'zh' || code === 'zh-cn' || code === 'zh-sg' || code.startsWith('zh-hans')) return 'zh-CN';
      const base = code.split('-')[0];
      if (Object.hasOwn(copies, base)) return base;
    }
    return 'en';
  }
  select.addEventListener('change', () => {
    const language = Object.hasOwn(copies, select.value) ? select.value : 'en';
    render(language);
    try { localStorage.setItem('gys:help-lang', language); } catch { /* Storage is optional for help. */ }
    const url = new URL(location.href);
    url.searchParams.set('lang', language);
    history.replaceState(null, '', url);
  });
  const requested = new URL(location.href).searchParams.get('lang') || storedLanguage() || deviceLanguage();
  select.value = Object.hasOwn(copies, requested) ? requested : 'en';
  // Reuse the existing page and wallet explainer language listeners.
  select.dispatchEvent(new Event('change'));
  window.addEventListener('hashchange', () => revealHash(true));
  revealHash(true);
})();
